import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  estimate1RM,
  warmupPercents,
  weekPercents,
  roundToPlate,
} from "../lib/tm";
import { loadProfile as loadProfileLocal } from "../lib/storage";
import {
  loadProfileRemote,
  saveProfile,
  saveSession,
  updateSession,
  bestEst1RM,
  recentSessions,
  defaultEquipment,
  getStoredTeamSelection,
  type Team,
  type Profile,
  type SessionRecord,
} from "../lib/db";
import CoachTips from "../components/CoachTips";
import TrendMini from "../components/TrendMini";
import { useActiveAthlete } from "../context/ActiveAthleteContext";
import { PlateCalculatorDisplay } from "../components/PlateMath";
import { useDevice } from "../lib/device";
import { useAuth } from "../lib/auth";
import { useToast } from "../context/ToastContext";

type Lift = "bench" | "squat" | "deadlift";
type Week = 1 | 2 | 3;
type Unit = "lb" | "kg";

type SetOutcome = { status: "" | "S" | "F"; actualReps: string };

const warmRepLabels = ["5", "5", "3"];
const workRepLabels: Record<Week, [string, string, string]> = {
  1: ["5", "5", "5+"],
  2: ["3", "3", "3+"],
  3: ["5", "3", "1+"],
};

const LIFT_LABELS: Record<Lift, string> = {
  bench: "Bench Press",
  squat: "Back Squat",
  deadlift: "Deadlift",
};

const trainingMaxIncrement = (lift: Lift, unit: Unit): number => {
  const isLower = lift === "squat" || lift === "deadlift";
  return unit === "kg" ? (isLower ? 5 : 2.5) : (isLower ? 10 : 5);
};

const bumpTrainingMax = (
  tm: Profile["tm"] | undefined,
  lift: Lift,
  unit: Unit
): Profile["tm"] | undefined => {
  if (!tm) return tm;
  const current = tm[lift];
  if (typeof current !== "number" || !Number.isFinite(current)) return tm;
  const increment = trainingMaxIncrement(lift, unit);
  return { ...tm, [lift]: Number((current + increment).toFixed(2)) };
};

const adjustTrainingMaxByCycles = (
  tm: Profile["tm"] | undefined,
  lift: Lift,
  unit: Unit,
  deltaCycles: number
): Profile["tm"] | undefined => {
  if (!tm || !Number.isFinite(deltaCycles) || deltaCycles === 0) return tm;
  const current = tm[lift];
  if (typeof current !== "number" || !Number.isFinite(current)) return tm;
  const increment = trainingMaxIncrement(lift, unit);
  const next = current + increment * deltaCycles;
  return { ...tm, [lift]: Number(Math.max(0, next).toFixed(2)) };
};

const WEEK_THEMES: Record<Week, { name: string; focus: string; blurb: string }> = {
  1: {
    name: "Foundation Volume",
    focus: "Set The Tone With Crisp Sets Of Five.",
    blurb: "Smooth Technique And Steady Breathing Build Momentum For The Cycle.",
  },
  2: {
    name: "Power Triples",
    focus: "Drive Explosively Through The Sticking Point.",
    blurb: "Sharpen Power Output And Keep One Rep In The Tank On Every Set.",
  },
  3: {
    name: "Peak Week",
    focus: "Prime The Nervous System And Chase A Confident AMRAP.",
    blurb: "Own Each Top Set And Push Smartly Into PR Territory.",
  },
};

const clampCycle = (value: number): number => {
  if (!Number.isFinite(value) || value < 1) return 1;
  return Math.min(3, Math.floor(value));
};

const nextCycleAfter = (value: number): number => {
  const normalized = clampCycle(value);
  return normalized >= 3 ? 1 : normalized + 1;
};

const toLocalDayKey = (value: number): string => {
  const date = new Date(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const isSameLocalDay = (value: number, reference = Date.now()): boolean =>
  toLocalDayKey(value) === toLocalDayKey(reference);

const hasLiftWeekMap = (profile: Profile | null): boolean =>
  Boolean(profile?.liftWeeks && Object.keys(profile.liftWeeks).length > 0);

const hasLiftCycleMap = (profile: Profile | null): boolean =>
  Boolean(profile?.liftCycles && Object.keys(profile.liftCycles).length > 0);

const resolveLiftWeek = (profile: Profile | null, lift: Lift): Week => {
  const direct = profile?.liftWeeks?.[lift];
  if (direct === 1 || direct === 2 || direct === 3) return direct;
  if (!hasLiftWeekMap(profile)) {
    const fallback = profile?.currentWeek;
    if (fallback === 1 || fallback === 2 || fallback === 3) return fallback;
  }
  return 1;
};

const resolveLiftCycle = (profile: Profile | null, lift: Lift): number => {
  const direct = profile?.liftCycles?.[lift];
  if (typeof direct === "number" && Number.isFinite(direct)) {
    return clampCycle(direct);
  }
  if (!hasLiftCycleMap(profile)) {
    return clampCycle(profile?.currentCycle ?? 1);
  }
  return 1;
};

export default function Session() {
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const showToast = useToast();
  const [lift, setLift] = useState<Lift>(() => {
    const state = location.state as { lift?: Lift } | null;
    return state?.lift || "bench";
  });
  const [week, setWeek] = useState<Week>(1);
  const [cycle, setCycle] = useState<number>(1);
  const [unit, setUnit] = useState<Unit>("lb");
  const [tm, setTm] = useState<number | null>(null);
  const [sessionMode, setSessionMode] = useState<"simple" | "full">("simple");
  const [sessionSettingsOpen, setSessionSettingsOpen] = useState(false);
  const [currentSetIndex, setCurrentSetIndex] = useState(0);
  const [restTimer, setRestTimer] = useState(0);
  const [timerActive, setTimerActive] = useState(false);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [liftConfirmed, setLiftConfirmed] = useState(false);
  const [showWeekAdvancePrompt, setShowWeekAdvancePrompt] = useState(false);
  const [showPrPopup, setShowPrPopup] = useState(false);
  const [allEstMaxes, setAllEstMaxes] = useState<Record<Lift, number>>({ squat: 0, bench: 0, deadlift: 0 });
  const [allPrFlags, setAllPrFlags] = useState<Record<Lift, boolean>>({ squat: false, bench: false, deadlift: false });
  const [pendingPostSave, setPendingPostSave] = useState<(() => void) | null>(null);
  const [plateCalcTarget, setPlateCalcTarget] = useState<number | null>(null);
  const [teamSelection, setTeamSelection] = useState<Team | "">(() => getStoredTeamSelection());
  const autoAdvanceRef = useRef(false);
  const savingRef = useRef(false);

  const [step, setStep] = useState(5);
  const [amrapReps, setAmrapReps] = useState<number>(0);
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  const [history, setHistory] = useState<any[]>([]);
  const [est, setEst] = useState<number | null>(null);
  const [prFlag, setPrFlag] = useState<boolean>(false);
  const [warmOutcomes, setWarmOutcomes] = useState<SetOutcome[]>([]);
  const [workOutcomes, setWorkOutcomes] = useState<SetOutcome[]>([]);
  const [existingTodaySession, setExistingTodaySession] = useState<SessionRecord | null>(null);
  const { activeAthlete, isCoach, loading: coachLoading, notifyProfileChange, version } = useActiveAthlete();
  const device = useDevice();
  const isMobileDevice = device.isMobile || (device.isTouch && !device.isDesktop);
  const targetUid = isCoach && activeAthlete ? activeAthlete.uid : undefined;
  const activeAthleteName = activeAthlete
    ? [activeAthlete.firstName, activeAthlete.lastName].filter(Boolean).join(" ") || activeAthlete.uid
    : "";

  const sessionTeam = (teamSelection || profile?.team || activeAthlete?.team) as Team | undefined;

  useEffect(() => {
    if (typeof window === "undefined") return;
    const readTeam = () => setTeamSelection(getStoredTeamSelection());
    readTeam();
    const handleStorage = (event: StorageEvent) => {
      if (event.key === "pl-strength-team") {
        readTeam();
      }
    };
    const handleCustom = () => readTeam();
    window.addEventListener("storage", handleStorage);
    window.addEventListener("pl-team-change", handleCustom);
    return () => {
      window.removeEventListener("storage", handleStorage);
      window.removeEventListener("pl-team-change", handleCustom);
    };
  }, []);

  useEffect(() => {
    setShowWeekAdvancePrompt(false);
    setLiftConfirmed(false);
  }, [sessionTeam]);


  useEffect(() => {
    (async () => {
      // If no user, fall back to local profile only
      if (!user) {
        const local = loadProfileLocal();
        if (local) {
          setProfile(local);
          const nextUnit = (local.unit || "lb") as Unit;
          setUnit(nextUnit);
          setStep(nextUnit === "lb" ? 5 : 2.5);
          const tmForLift = local.tm?.[lift] ?? null;
          setTm(tmForLift ?? null);
          if (local.sessionMode) {
            setSessionMode(local.sessionMode);
          }
        } else {
          setProfile(null);
          setTm(null);
        }
        return;
      }
      if (targetUid) {
        const p = await loadProfileRemote(targetUid);
        if (p) {
          setProfile(p);
          const nextUnit = (p.unit || "lb") as Unit;
          setUnit(nextUnit);
          setStep(nextUnit === "lb" ? 5 : 2.5);
          const tmForLift = p.tm?.[lift] ?? null;
          setTm(tmForLift ?? null);
          const nextWeek = resolveLiftWeek(p, lift);
          const nextCycle = resolveLiftCycle(p, lift);
          if (!liftConfirmed) {
            setWeek(nextWeek);
            setCycle(nextCycle);
          }
          // Load saved session mode preference
          if (p.sessionMode) {
            setSessionMode(p.sessionMode);
          }
        } else {
          setProfile(null);
          setUnit("lb");
          setStep(5);
          setTm(null);
        }
      } else {
        const remote = await loadProfileRemote();
        const local = loadProfileLocal();
        const p = remote || local;
        if (p) {
          setProfile(p);
          const nextUnit = (p.unit || "lb") as Unit;
          setUnit(nextUnit);
          setStep(nextUnit === "lb" ? 5 : 2.5);
          const tmForLift = p.tm?.[lift] ?? null;
          setTm(tmForLift ?? null);
          const nextWeek = resolveLiftWeek(p, lift);
          const nextCycle = resolveLiftCycle(p, lift);
          if (!liftConfirmed) {
            setWeek(nextWeek);
            setCycle(nextCycle);
          }
          // Load saved session mode preference
          if (p.sessionMode) {
            setSessionMode(p.sessionMode);
          }
        } else {
          setProfile(null);
          setTm(null);
        }
      }
      setAmrapReps(0);
      setNote("");
      setPrFlag(false);
    })();
  }, [lift, targetUid, version, teamSelection, user]);

  const warm = useMemo(() => {
    if (!tm) return [];
    return warmupPercents().map((pct, index) => ({
      pct,
      weight: roundToPlate(tm * pct, unit, step),
      reps: Number(warmRepLabels[index]),
      repsDisplay: warmRepLabels[index],
    }));
  }, [tm, unit, step]);

  const work = useMemo(() => {
    if (!tm) return [];
    const percents = weekPercents(week);
    const repsDisplay = workRepLabels[week];
    const numericReps = week === 1 ? [5, 5, 5] : week === 2 ? [3, 3, 3] : [5, 3, 1];
    return percents.map((pct, index) => ({
      pct,
      weight: roundToPlate(tm * pct, unit, step),
      reps: numericReps[index],
      repsDisplay: repsDisplay[index],
    }));
  }, [tm, unit, step, week]);

  useEffect(() => {
    setWarmOutcomes(warm.map(() => ({ status: "", actualReps: "" })));
  }, [warm]);

  useEffect(() => {
    setWorkOutcomes(work.map(() => ({ status: "", actualReps: "" })));
  }, [work]);

  const lastWorkWeight = work[2]?.weight || 0;

  useEffect(() => {
    if (!tm || work.length === 0 || amrapReps <= 0) {
      setEst(null);
      return;
    }
    const estimate = estimate1RM(lastWorkWeight, amrapReps);
    setEst(roundToPlate(estimate, unit, step));
  }, [amrapReps, work, tm, lastWorkWeight]);

  useEffect(() => {
    if (coachLoading) return;
    if (!user) {
      setHistory([]);
      return;
    }
    if (isCoach && !targetUid) {
      setHistory([]);
      return;
    }
    (async () => {
      const rows = await recentSessions(lift, 12, targetUid, sessionTeam);
      // rows are returned newest-first (descending).
      // We reverse them for the chart (oldest-first).
      const chartHistory = [...rows].reverse();
      setHistory(chartHistory);

      // Smart Default Logic:
      // If the user hasn't manually picked a week yet (liftConfirmed is false),
      // try to guess the next week based on the most recent session for this lift.
      const hasLiftProgress =
        typeof profile?.liftWeeks?.[lift] === "number" ||
        typeof profile?.liftCycles?.[lift] === "number";
      if (!liftConfirmed && rows.length > 0 && !hasLiftProgress) {
        const lastSession = rows[0]; // Newest session
        const lastWeek = lastSession.week;
        const lastCycle = lastSession.cycle ?? 1;
        // Simple cycle logic: 1->2->3->1
        const nextWeek: Week = lastWeek === 1 ? 2 : lastWeek === 2 ? 3 : 1;
        const nextCycle = lastWeek === 3 ? nextCycleAfter(lastCycle) : lastCycle;
        setWeek(nextWeek);
        setCycle(clampCycle(nextCycle));
      }
    })();
  }, [lift, targetUid, isCoach, coachLoading, version, liftConfirmed, sessionTeam, profile, user]);

  const setWarmStatus = (index: number, status: "" | "S" | "F") => {
    setWarmOutcomes((prev) => {
      const next = [...prev];
      const current = next[index] ?? { status: "", actualReps: "" };
      next[index] = {
        status,
        actualReps: status === "F" ? current.actualReps : "",
      };
      return next;
    });
  };

  const setWarmActual = (index: number, value: string) => {
    setWarmOutcomes((prev) => {
      const next = [...prev];
      next[index] = { status: "F", actualReps: value };
      return next;
    });
  };

  const setWorkStatus = (index: number, status: "" | "S" | "F") => {
    setWorkOutcomes((prev) => {
      const next = [...prev];
      const current = next[index] ?? { status: "", actualReps: "" };
      next[index] = {
        status,
        actualReps: status === "F" ? current.actualReps : "",
      };
      return next;
    });
  };

  const setWorkActual = (index: number, value: string) => {
    setWorkOutcomes((prev) => {
      const next = [...prev];
      next[index] = { status: "F", actualReps: value };
      return next;
    });
  };

  const statusValue = (outcome?: SetOutcome): "S" | "F" | undefined =>
    outcome?.status === "S" || outcome?.status === "F" ? outcome.status : undefined;

  const actualValue = (outcome?: SetOutcome): number | undefined => {
    if (!outcome || outcome.status !== "F") return undefined;
    const parsed = Number(outcome.actualReps);
    if (!Number.isFinite(parsed) || parsed < 0) return undefined;
    return parsed;
  };

  const mergeSets = (
    sets: Array<{ pct: number; weight: number; reps: number }>,
    outcomes: SetOutcome[]
  ) =>
    sets.map((set, index) => {
      const status = statusValue(outcomes[index]);
      const actual = actualValue(outcomes[index]);
      return {
        ...set,
        ...(status ? { status } : {}),
        ...(typeof actual === "number" ? { actualReps: actual } : {}),
      };
    });

  async function save(options?: { allowUpdate?: boolean }) {
    // Prevent duplicate submissions from rapid clicks
    if (savingRef.current) return;
    savingRef.current = true;

    if (!tm || work.length === 0 || amrapReps <= 0) {
      savingRef.current = false;
      showToast("Set a training max and enter AMRAP reps.", "warning");
      return;
    }
    // Exclude the last work set (AMRAP) — its reps are captured via amrapReps, not workOutcomes
    const missingActual = [...warmOutcomes, ...workOutcomes.slice(0, workOutcomes.length - 1)].some(
      (outcome) => outcome?.status === "F" && !outcome.actualReps.trim()
    );
    if (missingActual) {
      savingRef.current = false;
      showToast("Enter the actual reps completed for any set marked as a fail.", "warning");
      return;
    }

    const warmWithResults = mergeSets(warm, warmOutcomes);
    const workWithResults = mergeSets(work, workOutcomes);

    if (options?.allowUpdate) {
      setExistingTodaySession(null);
    }

    setSaving(true);
    try {
      const recent = await recentSessions(lift, 25, targetUid, sessionTeam);
      const existingForToday = recent.find((row) => {
        if (row.source !== "remote" || !row.id) return false;
        const createdAt = typeof row.createdAt === "number" ? row.createdAt : 0;
        return createdAt > 0 && isSameLocalDay(createdAt);
      });

      if (existingForToday && !options?.allowUpdate) {
        setExistingTodaySession(existingForToday);
        savingRef.current = false; // Allow re-save after user resolves the duplicate prompt
        return;
      }

      const est1rm = roundToPlate(estimate1RM(lastWorkWeight, amrapReps), unit, step);
      const best = await bestEst1RM(lift, 20, targetUid, sessionTeam);
      const pr = est1rm > best;

      const payload = {
        lift,
        week,
        cycle,
        team: sessionTeam,
        unit,
        tm,
        warmups: warmWithResults,
        work: workWithResults,
        amrap: { weight: lastWorkWeight, reps: amrapReps },
        est1rm,
        note,
        pr,
      };

      if (existingForToday?.id) {
        const ownerUid = targetUid ?? user?.uid;
        if (!ownerUid) {
          throw new Error("Unable to resolve athlete UID for session update.");
        }
        await updateSession(ownerUid, existingForToday.id, payload);
      } else {
        await saveSession(payload, targetUid, { requireRemote: !!targetUid });
      }

      setExistingTodaySession(null);

      setPrFlag(pr);
      setEst(est1rm);

      // Fetch best est1rm for all 3 lifts to display in popup
      const allLifts: Lift[] = ["squat", "bench", "deadlift"];
      const otherLifts = allLifts.filter((l) => l !== lift);
      const [other1, other2] = await Promise.all(
        otherLifts.map((l) => bestEst1RM(l, 20, targetUid, sessionTeam))
      );
      const maxes: Record<Lift, number> = { squat: 0, bench: 0, deadlift: 0 };
      maxes[lift] = est1rm;
      maxes[otherLifts[0]] = other1;
      maxes[otherLifts[1]] = other2;
      const prFlags: Record<Lift, boolean> = { squat: false, bench: false, deadlift: false };
      prFlags[lift] = pr;
      setAllEstMaxes(maxes);
      setAllPrFlags(prFlags);

      if (week === 3) {
        // Defer week advance until popup is closed
        setPendingPostSave(() => async () => {
          autoAdvanceRef.current = true;
          const nextCyc = nextCycleAfter(cycle);
          const resetCycle = clampCycle(cycle) === 3;
          await advanceWeek();
          showToast(
            resetCycle
              ? `Week 3 complete. ${LIFT_LABELS[lift]} reset to Cycle 1. Re-test your 1RM and start Week 1.`
              : `Week 3 complete. ${LIFT_LABELS[lift]} moved to Cycle ${nextCyc}. Training max updated.`,
            "success"
          );
          navigate("/");
        });
      } else {
        const rows = await recentSessions(lift, 12, targetUid, sessionTeam);
        setHistory(rows.reverse());
        notifyProfileChange();

        if (sessionMode === "simple") {
          setPendingPostSave(() => () => navigate("/"));
        } else {
          setPendingPostSave(() => () => setShowWeekAdvancePrompt(true));
        }
      }
      setShowPrPopup(true);
      // Keep savingRef.current = true after success — prevents any re-save until
      // the component unmounts (navigation away). Only reset on failure so retries work.
    } catch (err) {
      console.warn("Failed to save session", err);
      showToast("Unable to save session right now. Please try again.", "error");
      savingRef.current = false;
    } finally {
      setSaving(false);
      autoAdvanceRef.current = false;
    }
  }

  const persistLiftProgress = async (
    nextWeek: Week,
    nextCycle: number,
    nextTm?: Profile["tm"]
  ) => {
    const clampedCycle = clampCycle(nextCycle);
    setWeek(nextWeek);
    setCycle(clampedCycle);
    setLiftConfirmed(true);
    if (!profile) return;
    const nextLiftWeeks = { ...(profile.liftWeeks ?? {}) };
    nextLiftWeeks[lift] = nextWeek;
    const nextLiftCycles = { ...(profile.liftCycles ?? {}) };
    nextLiftCycles[lift] = clampedCycle;
    const updatedProfile: Profile = {
      ...profile,
      liftWeeks: nextLiftWeeks,
      liftCycles: nextLiftCycles,
      currentWeek: nextWeek,
      currentCycle: clampedCycle,
      tm: nextTm ?? profile.tm,
    };
    await saveProfile(updatedProfile, { skipLocal: Boolean(targetUid), requireRemote: true });
    setProfile(updatedProfile);
    const nextTmValue = updatedProfile.tm?.[lift];
    setTm(typeof nextTmValue === "number" && Number.isFinite(nextTmValue) ? nextTmValue : null);
    notifyProfileChange();
  };

  // Toggle and save session mode preference
  const toggleSessionMode = async () => {
    const newMode = sessionMode === "simple" ? "full" : "simple";
    setSessionMode(newMode);
    setCurrentSetIndex(0); // Reset to first set when switching modes
    
    // Save to profile so it syncs across devices
    if (profile) {
      const updatedProfile: Profile = { ...profile, sessionMode: newMode };
      await saveProfile(updatedProfile, { skipLocal: Boolean(targetUid), requireRemote: true });
      setProfile(updatedProfile);
      notifyProfileChange();
    }
  };

  // Handle week change and save to profile
  const handleWeekChange = async (newWeek: Week) => {
    await persistLiftProgress(newWeek, cycle);
  };

  const handleCycleChange = async (newCycle: number) => {
    const normalized = clampCycle(newCycle);
    const baseCycle = profile ? resolveLiftCycle(profile, lift) : clampCycle(cycle);
    const delta = normalized - baseCycle;
    const nextTm =
      delta === 0 ? profile?.tm : adjustTrainingMaxByCycles(profile?.tm, lift, unit, delta);
    await persistLiftProgress(week, normalized, nextTm);
  };

  // Advance to next week (1->2->3->1) and bump TMs on new cycle
  const advanceWeek = async () => {
    const alreadyLocked = autoAdvanceRef.current;
    if (!alreadyLocked) autoAdvanceRef.current = true;
    const effectiveWeek: Week = week;
    try {
      if (effectiveWeek === 3) {
        const currentCycle = clampCycle(cycle);
        const nextCycle = nextCycleAfter(currentCycle);
        const nextTm =
          currentCycle === 3 ? profile?.tm : bumpTrainingMax(profile?.tm, lift, unit);
        await persistLiftProgress(1, nextCycle, nextTm);
      } else {
        const nextWeek: Week = effectiveWeek === 1 ? 2 : 3;
        await persistLiftProgress(nextWeek, cycle);
      }
      setShowWeekAdvancePrompt(false);
    } finally {
      // Only release the lock if we acquired it ourselves.
      // When save() pre-locks the ref, it stays locked until
      // save() finishes so the useEffect can't double-fire.
      if (!alreadyLocked) autoAdvanceRef.current = false;
    }
  };

  const maybeAutoAdvanceWeek3 = async () => {
    if (autoAdvanceRef.current) return false;
    if (!profile) return false;
    const effectiveWeek = resolveLiftWeek(profile, lift);
    const effectiveCycle = resolveLiftCycle(profile, lift);
    if (effectiveWeek !== 3) return false;
    const latest = history[history.length - 1];
    if (!latest || latest.week !== 3) return false;
    if (clampCycle(latest.cycle ?? 1) !== effectiveCycle) return false;
    setShowWeekAdvancePrompt(false);
    await advanceWeek();
    return true;
  };

  useEffect(() => {
    void maybeAutoAdvanceWeek3();
  }, [history, profile, lift, cycle, week]);

  const estSeries = history
    .map((row) =>
      typeof row.est1rm === "number"
        ? roundToPlate(
            row.est1rm,
            row.unit,
            row.unit === "lb" ? 5 : 2.5
          )
        : undefined
    )
    .filter((value): value is number => typeof value === "number" && !Number.isNaN(value));
  const prevBest = estSeries.length ? Math.max(...estSeries) : 0;

  // Rest timer countdown
  useEffect(() => {
    if (!timerActive || restTimer <= 0) {
      setTimerActive(false);
      return;
    }
    
    const interval = setInterval(() => {
      setRestTimer(prev => {
        if (prev <= 1) {
          setTimerActive(false);
          // Play a sound or vibrate on completion
          if ('vibrate' in navigator) {
            navigator.vibrate([200, 100, 200]);
          }
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    
    return () => clearInterval(interval);
  }, [timerActive, restTimer]);

  const startRestTimer = (seconds: number) => {
    setRestTimer(seconds);
    setTimerActive(true);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const allSets = [...warm.map((s, i) => ({ ...s, phase: 'warm' as const, index: i })), 
                   ...work.map((s, i) => ({ ...s, phase: 'work' as const, index: i }))];

  const theme = WEEK_THEMES[week];
  const liftLabel = LIFT_LABELS[lift];
  const cycleNumber = cycle;
  const quickStats = [
    { label: "Lift", value: liftLabel },
    { label: "Week", value: `Cycle ${cycleNumber} / Week ${week} | ${theme.name}` },
    {
      label: "Training Max",
      value: tm && Number.isFinite(tm) ? `${tm} ${unit}` : "Set in Calculator",
    },
    {
      label: "Best Est. 1RM",
      value: prevBest > 0 ? `${prevBest} ${unit}` : "Log a session",
    },
  ];
  const heroBadge = targetUid
    ? `Working with ${activeAthleteName}`
    : "Personal session";

  const existingSessionModal = existingTodaySession ? (
    <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div className="w-full max-w-md rounded-3xl bg-white p-6 shadow-2xl space-y-4">
        <div className="space-y-1">
          <h3 className="text-xl font-bold text-gray-900">Lift Already Recorded Today</h3>
          <p className="text-sm text-gray-600">
            A {LIFT_LABELS[lift]} session is already saved with{" "}
            <span className="font-semibold text-gray-900">
              {existingTodaySession.amrap?.weight ?? 0} {existingTodaySession.unit} x{" "}
              {existingTodaySession.amrap?.reps ?? 0}
            </span>
            .
          </p>
          <p className="text-sm text-gray-600">Do you want to update that entry?</p>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button
            type="button"
            onClick={() => setExistingTodaySession(null)}
            className="px-4 py-2 rounded-xl border border-gray-200 text-gray-700 font-semibold hover:bg-gray-50"
          >
            Keep Existing
          </button>
          <button
            type="button"
            onClick={() => void save({ allowUpdate: true })}
            className="px-4 py-2 rounded-xl bg-brand-600 text-white font-semibold hover:bg-brand-700"
          >
            Update Entry
          </button>
        </div>
      </div>
    </div>
  ) : null;

  if (coachLoading) {
    return (
      <div className="container py-6">
        <div className="card text-sm text-gray-600">Loading coach tools...</div>
      </div>
    );
  }

  // Simple Mode - Full screen step-by-step wizard UI
  if (sessionMode === "simple" && tm) {
    const currentSet = allSets[currentSetIndex];
    const isLastSet = currentSetIndex === allSets.length - 1;
    const isAMRAPSet = currentSet?.phase === 'work' && currentSetIndex === allSets.length - 1;
    
    return (
      <>
        {existingSessionModal}
        {plateCalcTarget !== null && (
          <div
            className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
            onClick={() => setPlateCalcTarget(null)}
          >
            <div
              className="w-full max-w-2xl rounded-3xl bg-gray-900 p-1 shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="rounded-[20px] bg-gray-900 p-6 space-y-4 border border-gray-800">
                <div className="flex justify-between items-center">
                  <h3 className="text-xl font-bold text-white">Plate Math</h3>
                  <button
                    onClick={() => setPlateCalcTarget(null)}
                    className="text-gray-400 hover:text-white px-3 py-1 rounded-lg hover:bg-gray-800"
                  >
                    Close
                  </button>
                </div>
                <PlateCalculatorDisplay
                  targetWeight={plateCalcTarget}
                  unit={unit}
                  equipment={profile?.equipment ?? defaultEquipment()}
                />
              </div>
            </div>
          </div>
        )}

        <div
          className={`fixed inset-0 z-50 text-white flex flex-col overflow-hidden relative ${
            currentSet?.phase === 'warm'
              ? 'bg-gradient-to-br from-blue-600 to-blue-800'
              : 'bg-black'
          }`}
        >
          {/* Dragon logo background for work sets */}
          {currentSet?.phase === 'work' && (
            <div
              className="absolute inset-0 bg-center bg-contain bg-no-repeat opacity-15 pointer-events-none"
              style={{ backgroundImage: 'url(/assets/dragon.png)' }}
            />
          )}
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-white/20 flex-shrink-0">
          <div>
            <div className="text-xs opacity-80">Cycle {cycleNumber} · Week {week}</div>
            <div className="text-lg font-bold">{LIFT_LABELS[lift]}</div>
          </div>
          <button
            onClick={toggleSessionMode}
            className="px-3 py-1.5 bg-white/20 hover:bg-white/30 rounded-lg font-semibold text-sm"
          >
            Full View
          </button>
        </div>

        {/* Scrollable Content Area */}
        <div className="flex-1 overflow-y-auto overflow-x-hidden">
          {/* Set Counter */}
          <div className="px-4 py-3 text-center">
            <div className={`text-xl font-black uppercase tracking-wide ${
              currentSet?.phase === 'warm' ? 'text-blue-200' : 'text-red-400'
            }`} style={currentSet?.phase === 'work' ? { textShadow: '0 0 20px rgba(248, 113, 113, 0.8)' } : undefined}>
              {currentSet?.phase === 'warm' ? 'WARM UP SET' : 'WORK SET'}
            </div>
            <div className="text-5xl font-bold my-1" style={currentSet?.phase === 'work' ? { textShadow: '0 0 30px rgba(255, 255, 255, 0.5)' } : undefined}>
              {currentSetIndex + 1} / {allSets.length}
            </div>
          </div>

          {/* Current Set Info */}
          {currentSet && (
            <div className="px-4 py-2 space-y-4">
              <div className="text-center space-y-3">
                <div className="text-8xl font-black leading-none">
                  {currentSet.weight}
                </div>
                <div className="text-2xl opacity-90">{unit}</div>
                {Number.isFinite(currentSet.weight) && currentSet.weight > 0 && (
                  <button
                    type="button"
                    onClick={() => setPlateCalcTarget(currentSet.weight)}
                    className="mx-auto inline-flex items-center gap-2 rounded-full bg-white/15 px-3 py-1 text-xs font-semibold text-white/90 hover:bg-white/25"
                  >
                    Plate Calc
                  </button>
                )}
                <div className="text-xl mt-2">
                  {currentSet.phase === 'warm'
                    ? `${warmRepLabels[currentSet.index]} reps`
                    : `${workRepLabels[week][currentSet.index]} reps`
                  }
                </div>
                <div className="text-base opacity-70">
                  {Math.round(currentSet.pct * 100)}% of TM
                </div>
                {isAMRAPSet && (
                  <div className="mt-4 mx-4 px-4 py-2 rounded-xl border-2 bg-red-500/20 border-red-400">
                    <div className="text-xl font-bold text-red-300" style={{ textShadow: '0 0 15px rgba(248, 113, 113, 0.8)' }}>AMRAP SET!</div>
                    <div className="text-xs mt-1">Leave 1-2 Reps In The Tank</div>
                  </div>
                )}
              </div>

              {/* Rest Timer */}
              {timerActive && (
                <div className="text-center space-y-2 py-4">
                  <div className="text-xs uppercase tracking-wide opacity-80">Rest Timer</div>
                  <div className="text-6xl font-bold text-yellow-300">
                    {formatTime(restTimer)}
                  </div>
                  <button
                    onClick={() => setTimerActive(false)}
                    className="px-4 py-1.5 bg-white/20 hover:bg-white/30 rounded-lg text-sm"
                  >
                    Cancel Timer
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Fixed Action Buttons at Bottom */}
        <div className="px-4 py-4 space-y-2 bg-gradient-to-t from-black/20 to-transparent flex-shrink-0 border-t border-white/10">
          {!timerActive && currentSet && (
            <>
              {/* Rest Timer Shortcuts */}
              <div className="grid grid-cols-3 gap-2">
                <button
                  onClick={() => startRestTimer(60)}
                  className="py-3 bg-blue-500/30 hover:bg-blue-500/40 rounded-xl font-semibold"
                >
                  1:00
                </button>
                <button
                  onClick={() => startRestTimer(120)}
                  className="py-3 bg-blue-500/30 hover:bg-blue-500/40 rounded-xl font-semibold"
                >
                  2:00
                </button>
                <button
                  onClick={() => startRestTimer(180)}
                  className="py-3 bg-blue-500/30 hover:bg-blue-500/40 rounded-xl font-semibold"
                >
                  3:00
                </button>
              </div>

              {/* Mark Success/Fail - or Save Session for last AMRAP set */}
              {!isAMRAPSet ? (
                <div className="grid grid-cols-2 gap-2">
                  <button
                    onClick={() => {
                      if (currentSet.phase === 'warm') {
                        setWarmStatus(currentSet.index, 'S');
                      } else {
                        setWorkStatus(currentSet.index, 'S');
                      }
                      if (!isLastSet) {
                        setCurrentSetIndex(prev => prev + 1);
                        // Only auto-start timer if NEXT set is also a work set (not transitioning from warm-up)
                        const nextSet = allSets[currentSetIndex + 1];
                        if (currentSet.phase === 'work' && nextSet?.phase === 'work') {
                          startRestTimer(150); // Auto-start 2:30 rest between work sets
                        }
                      }
                    }}
                    className="py-5 bg-green-500 hover:bg-green-600 rounded-xl font-bold text-xl shadow-lg"
                  >
                    ✓ Done
                  </button>
                  <button
                    onClick={() => {
                      const reps = prompt('How Many Reps Did You Complete?');
                      if (reps) {
                        if (currentSet.phase === 'warm') {
                          setWarmStatus(currentSet.index, 'F');
                          setWarmActual(currentSet.index, reps);
                        } else {
                          setWorkStatus(currentSet.index, 'F');
                          setWorkActual(currentSet.index, reps);
                        }
                        if (!isLastSet) {
                          setCurrentSetIndex(prev => prev + 1);
                        }
                      }
                    }}
                    className="py-5 bg-red-500 hover:bg-red-600 rounded-xl font-bold text-xl shadow-lg"
                  >
                    ✗ Failed
                  </button>
                </div>
              ) : null}

              {/* Navigation - smaller and less prominent */}
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => setCurrentSetIndex(prev => Math.max(0, prev - 1))}
                  disabled={currentSetIndex === 0}
                  className="py-1.5 bg-white/5 hover:bg-white/10 rounded-lg disabled:opacity-20 text-xs opacity-60"
                >
                  ← Prev
                </button>
                <button
                  onClick={() => setCurrentSetIndex(prev => Math.min(allSets.length - 1, prev + 1))}
                  disabled={isLastSet}
                  className="py-1.5 bg-white/5 hover:bg-white/10 rounded-lg disabled:opacity-20 text-xs opacity-60"
                >
                  Next →
                </button>
              </div>

              {/* AMRAP input and Save Session button (replaces Done/Failed for last set) */}
              {isAMRAPSet && (
                <div className="space-y-3">
                  <div className="text-center">
                    <div className="text-sm opacity-80 mb-2">AMRAP Reps Completed</div>
                    <div className="flex items-center justify-center gap-4">
                      <button
                        onClick={() => setAmrapReps(prev => Math.max(0, prev - 1))}
                        className="w-14 h-14 rounded-full bg-white/20 text-2xl font-bold"
                      >
                        −
                      </button>
                      <div className="text-6xl font-black w-24 text-center">{amrapReps}</div>
                      <button
                        onClick={() => setAmrapReps(prev => prev + 1)}
                        className="w-14 h-14 rounded-full bg-white/20 text-2xl font-bold"
                      >
                        +
                      </button>
                    </div>
                  </div>
                  <button
                    onClick={save}
                    disabled={saving || amrapReps <= 0}
                    className="w-full py-5 bg-green-500 hover:bg-green-600 disabled:bg-gray-400 disabled:opacity-50 rounded-xl font-bold text-xl shadow-lg"
                  >
                    {saving ? "Saving..." : amrapReps > 0 ? "✓ Save Session" : "Enter Reps Above"}
                  </button>
                </div>
              )}
            </>
          )}
        </div>
        </div>

        {/* PR / Estimated Max Popup (Simple Mode) */}
        {showPrPopup && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
            <div className="w-full max-w-sm rounded-3xl bg-gray-950 p-6 shadow-2xl space-y-5 animate-in fade-in zoom-in duration-200 border border-gray-800">
              <div className="text-center space-y-1">
                {Object.values(allPrFlags).some(Boolean) ? (
                  <h3 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 via-amber-400 to-yellow-300 pr-shimmer">
                    New Personal Record
                  </h3>
                ) : (
                  <h3 className="text-xl font-bold text-white">Session Complete</h3>
                )}
                <p className="text-sm text-gray-400">Estimated Max Overview</p>
              </div>
              <div className="space-y-3">
                {(["squat", "bench", "deadlift"] as Lift[]).map((l) => {
                  const isPr = allPrFlags[l];
                  const value = allEstMaxes[l];
                  const liftColors: Record<Lift, { bg: string; border: string; text: string; accent: string }> = {
                    squat: { bg: "bg-red-950/60", border: "border-red-700/50", text: "text-red-300", accent: "text-red-100" },
                    bench: { bg: "bg-blue-950/60", border: "border-blue-700/50", text: "text-blue-300", accent: "text-blue-100" },
                    deadlift: { bg: "bg-purple-950/60", border: "border-purple-700/50", text: "text-purple-300", accent: "text-purple-100" },
                  };
                  const colors = liftColors[l];
                  return (
                    <div
                      key={l}
                      className={`relative rounded-2xl border p-4 transition-all ${
                        isPr
                          ? "pr-glow border-yellow-400/80 bg-gradient-to-r from-yellow-950/50 via-amber-950/40 to-yellow-950/50"
                          : `${colors.bg} ${colors.border}`
                      }`}
                    >
                      <div className="flex items-center justify-between">
                        <div>
                          <div className={`text-xs font-semibold uppercase tracking-wider ${isPr ? "text-yellow-400" : colors.text}`}>
                            {LIFT_LABELS[l]}
                          </div>
                          <div className={`text-3xl font-black ${isPr ? "text-yellow-100" : colors.accent}`}>
                            {value > 0 ? `${value} ${unit}` : "—"}
                          </div>
                        </div>
                        {isPr && (
                          <span className="inline-flex items-center rounded-full border border-yellow-400/40 bg-yellow-500/15 px-2 py-0.5 text-[11px] font-bold uppercase tracking-wide text-yellow-200">
                            PR
                          </span>
                        )}
                      </div>
                      {isPr && (
                        <div className="mt-1">
                          <span className="inline-flex items-center gap-1 rounded-full bg-yellow-500/20 border border-yellow-400/40 px-2.5 py-0.5 text-xs font-bold text-yellow-300 uppercase tracking-wide">
                            New Personal Record
                          </span>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
              <button
                onClick={() => {
                  setShowPrPopup(false);
                  if (pendingPostSave) {
                    pendingPostSave();
                    setPendingPostSave(null);
                  }
                }}
                className="w-full py-4 rounded-2xl bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700 text-white font-bold text-lg shadow-lg transition-all"
              >
                Back to Home
              </button>
            </div>
          </div>
        )}
      </>
    );
  }

  return (
    <div className="container py-6 space-y-8">
      {existingSessionModal}
      {/* Week Advance Prompt Modal */}
      {showWeekAdvancePrompt && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="w-full max-w-md rounded-3xl bg-white p-6 shadow-2xl space-y-4">
            <div className="text-center space-y-2">
              <div className="text-4xl">🎉</div>
              <h3 className="text-xl font-bold text-gray-900">Week {week} Complete!</h3>
              <p className="text-sm text-gray-600">
                You've Logged {liftLabel} For Week {week}. Nice Work!
              </p>
            </div>
            <div className="rounded-2xl bg-emerald-50 border border-emerald-200 p-4 text-center">
              <p className="text-sm font-medium text-emerald-800">
                Ready To Advance {liftLabel} To Week {week === 3 ? 1 : week + 1} (Cycle {week === 3 ? nextCycleAfter(cycleNumber) : cycleNumber})?
              </p>
              {week === 3 && (
                <p className="mt-1 text-xs text-emerald-700">
                  {cycleNumber >= 3
                    ? "Cycle resets to 1. Re-test your 1RM before starting over."
                    : "Training Max will increase for this lift."}
                </p>
              )}
            </div>
            <div className="grid grid-cols-2 gap-3">
              <button
                onClick={() => setShowWeekAdvancePrompt(false)}
                className="px-4 py-3 rounded-xl border border-gray-200 text-gray-700 font-semibold hover:bg-gray-50"
              >
                Not Yet
              </button>
              <button
                onClick={advanceWeek}
                className="px-4 py-3 rounded-xl bg-emerald-500 text-white font-semibold hover:bg-emerald-600 shadow-lg"
              >
                Yes, Advance →
              </button>
            </div>
          </div>
        </div>
      )}

      {/* PR / Estimated Max Popup */}
      {showPrPopup && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="w-full max-w-sm rounded-3xl bg-gray-950 p-6 shadow-2xl space-y-5 animate-in fade-in zoom-in duration-200 border border-gray-800">
            {/* Header */}
            <div className="text-center space-y-1">
              {Object.values(allPrFlags).some(Boolean) ? (
                <h3 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 via-amber-400 to-yellow-300 pr-shimmer">
                  New Personal Record
                </h3>
              ) : (
                <h3 className="text-xl font-bold text-white">Session Complete</h3>
              )}
              <p className="text-sm text-gray-400">Estimated Max Overview</p>
            </div>

            {/* 3 Lift Cards */}
            <div className="space-y-3">
              {(["squat", "bench", "deadlift"] as Lift[]).map((l) => {
                const isPr = allPrFlags[l];
                const value = allEstMaxes[l];
                const liftColors: Record<Lift, { bg: string; border: string; text: string; accent: string }> = {
                  squat: { bg: "bg-red-950/60", border: "border-red-700/50", text: "text-red-300", accent: "text-red-100" },
                  bench: { bg: "bg-blue-950/60", border: "border-blue-700/50", text: "text-blue-300", accent: "text-blue-100" },
                  deadlift: { bg: "bg-purple-950/60", border: "border-purple-700/50", text: "text-purple-300", accent: "text-purple-100" },
                };
                const colors = liftColors[l];
                return (
                  <div
                    key={l}
                    className={`relative rounded-2xl border p-4 transition-all ${
                      isPr
                        ? "pr-glow border-yellow-400/80 bg-gradient-to-r from-yellow-950/50 via-amber-950/40 to-yellow-950/50"
                        : `${colors.bg} ${colors.border}`
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <div className={`text-xs font-semibold uppercase tracking-wider ${isPr ? "text-yellow-400" : colors.text}`}>
                          {LIFT_LABELS[l]}
                        </div>
                        <div className={`text-3xl font-black ${isPr ? "text-yellow-100" : colors.accent}`}>
                          {value > 0 ? `${value} ${unit}` : "—"}
                        </div>
                      </div>
                      {isPr && (
                        <span className="inline-flex items-center rounded-full border border-yellow-400/40 bg-yellow-500/15 px-2 py-0.5 text-[11px] font-bold uppercase tracking-wide text-yellow-200">
                          PR
                        </span>
                      )}
                    </div>
                    {isPr && (
                      <div className="mt-1">
                        <span className="inline-flex items-center gap-1 rounded-full bg-yellow-500/20 border border-yellow-400/40 px-2.5 py-0.5 text-xs font-bold text-yellow-300 uppercase tracking-wide">
                          New Personal Record
                        </span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Close Button */}
            <button
              onClick={() => {
                setShowPrPopup(false);
                if (pendingPostSave) {
                  pendingPostSave();
                  setPendingPostSave(null);
                }
              }}
              className="w-full py-4 rounded-2xl bg-gradient-to-r from-emerald-500 to-emerald-600 hover:from-emerald-600 hover:to-emerald-700 text-white font-bold text-lg shadow-lg transition-all"
            >
              Back to Home
            </button>
          </div>
        </div>
      )}

      {/* Plate Calculator Modal */}
      {plateCalcTarget !== null && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4"
          onClick={() => setPlateCalcTarget(null)}
        >
          <div
            className="w-full max-w-2xl rounded-3xl bg-gray-900 p-1 shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="rounded-[20px] bg-gray-900 p-6 space-y-4 border border-gray-800">
              <div className="flex justify-between items-center">
                <h3 className="text-xl font-bold text-white">Plate Math</h3>
                <button
                  onClick={() => setPlateCalcTarget(null)}
                  className="text-gray-400 hover:text-white px-3 py-1 rounded-lg hover:bg-gray-800"
                >
                  Close
                </button>
              </div>
              <PlateCalculatorDisplay
                targetWeight={plateCalcTarget}
                unit={unit}
                equipment={profile?.equipment ?? defaultEquipment()}
              />
            </div>
          </div>
        </div>
      )}

      {/* Prominent Week Selector Tabs */}
      <div className="rounded-2xl bg-gradient-to-r from-gray-900 to-gray-800 p-1 shadow-lg">
        <div className="grid grid-cols-3 gap-1">
          {([1, 2, 3] as Week[]).map((w) => {
            const isActive = week === w;
            // Check if this week was completed recently (in the last 3 sessions)
            // history is oldest->newest. We want to check the newest entries.
            const recentHistory = history.slice(-3); 
            // Use filter + pop instead of findLast for compatibility
            const lastDone = recentHistory.filter((h: any) => h.week === w).pop();
            const isDone = Boolean(lastDone);
            
            const weekTheme = WEEK_THEMES[w];
            const weekColors: Record<Week, string> = {
              1: "from-blue-500 to-blue-600",
              2: "from-emerald-500 to-emerald-600",
              3: "from-amber-500 to-amber-600",
            };
            return (
              <button
                key={w}
                onClick={() => handleWeekChange(w)}
                className={`relative rounded-xl px-2 py-3 text-center transition-all ${
                  isActive
                    ? `bg-gradient-to-br ${weekColors[w]} text-white shadow-lg scale-[1.02]`
                    : "bg-gray-700/50 text-gray-300 hover:bg-gray-700 hover:text-white"
                }`}
              >
                <div className="flex items-center justify-center gap-1">
                  <div className="text-xs font-medium uppercase tracking-wide opacity-80">
                    Week {w}
                  </div>
                  {isDone && !isActive && (
                    <span className="text-[10px] text-emerald-400" title="Completed Recently">✓</span>
                  )}
                </div>
                <div className={`text-lg font-bold ${isActive ? "" : "text-gray-100"}`}>
                  {w === 1 ? "65/75/85" : w === 2 ? "70/80/90" : "75/85/95"}
                </div>
                {isActive && (
                  <div className="mt-1 text-[10px] font-medium opacity-90 truncate">
                    {weekTheme.name}
                  </div>
                )}
                {isDone && isActive && (
                   <div className="absolute top-1 right-1 h-2 w-2 rounded-full bg-white/30" />
                )}
              </button>
            );
          })}
        </div>
      </div>

      <div className={`rounded-3xl border border-gray-100 bg-white p-6 shadow-lg ring-1 ring-gray-100/80 space-y-4 ${isMobileDevice ? 'hidden' : ''}`}>
        {/* Full header for desktop only */}
        <>
            <div className="flex flex-wrap items-start justify-between gap-4">
              <div className="space-y-1">
                <h1 className="text-2xl font-semibold text-gray-900">Let's Train</h1>
                <p className="text-sm font-semibold text-gray-700">
                  Cycle {cycleNumber} - Week {week} - {theme.name}
                </p>
                <p className="text-sm text-gray-600">{theme.focus}</p>
                <p className="text-xs text-gray-500">{theme.blurb}</p>
              </div>
              <span className="inline-flex items-center gap-2 rounded-full bg-brand-50 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-brand-700">
                {heroBadge}
              </span>
            </div>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
              {quickStats.map((stat) => (
                <div
                  key={stat.label}
                  className="rounded-2xl border border-gray-100 bg-gray-50 px-4 py-3 shadow-inner"
                >
                  <div className="text-[11px] uppercase tracking-wide text-gray-500">
                    {stat.label}
                  </div>
                  <div className="mt-1 text-lg font-semibold text-gray-900">
                    {stat.value}
                  </div>
                </div>
              ))}
            </div>
          </>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="space-y-6 lg:col-span-2">
          <div className="card space-y-6 bg-white/95 shadow-xl ring-1 ring-gray-100/80">
            <div className={`flex flex-col gap-3 border-b border-gray-100 ${isMobileDevice ? 'pb-3' : 'pb-4'}`}>
              {/* Mobile: Combined header with lift name, stats, and toggle */}
              {isMobileDevice ? (
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2 flex-wrap">
                    <h2 className="text-lg font-bold text-gray-900">{liftLabel}</h2>
                    <span className="bg-gray-100 text-gray-700 px-2 py-0.5 rounded-full text-xs font-medium">C{cycleNumber} W{week}</span>
                    <span className="text-xs text-gray-500">TM:{tm ?? '—'}</span>
                    <span className="text-xs text-gray-500">Best:{prevBest > 0 ? prevBest : '—'}</span>
                  </div>
                  {/* Mobile toggle */}
                  <div className="inline-flex items-center rounded-full bg-gray-100 p-0.5">
                    <button
                      onClick={() => sessionMode !== "simple" && toggleSessionMode()}
                      className={`p-1.5 rounded-full transition-all ${
                        sessionMode === "simple" ? "bg-brand-600 text-white shadow-sm" : "text-gray-500"
                      }`}
                      title="Simple"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <rect x="5" y="2" width="14" height="20" rx="2" ry="2"/>
                        <line x1="12" y1="18" x2="12" y2="18"/>
                      </svg>
                    </button>
                    <button
                      onClick={() => sessionMode !== "full" && toggleSessionMode()}
                      className={`p-1.5 rounded-full transition-all ${
                        sessionMode === "full" ? "bg-brand-600 text-white shadow-sm" : "text-gray-500"
                      }`}
                      title="Full"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>
                        <line x1="2" y1="20" x2="22" y2="20"/>
                      </svg>
                    </button>
                  </div>
                </div>
              ) : (
                /* Desktop: Original header */
                <>
                  <div className="space-y-1">
                    <span className="text-xs font-semibold uppercase tracking-[0.35em] text-brand-600">
                      Session Builder
                    </span>
                    <h3 className="text-2xl font-semibold text-gray-900">Let's Train - {liftLabel}</h3>
                  </div>
                  <div className="flex flex-wrap items-center gap-2">
                    {/* Simple/Full Mode Toggle */}
                    <div className="inline-flex items-center rounded-full bg-gray-100 p-1" title="Simple = step-by-step, Full = all details">
                      <button
                        onClick={() => sessionMode !== "simple" && toggleSessionMode()}
                        className={`p-2 rounded-full transition-all ${
                          sessionMode === "simple"
                            ? "bg-brand-600 text-white shadow-sm"
                            : "text-gray-500 hover:text-gray-900"
                        }`}
                        title="Simple Mode (Step-by-step)"
                      >
                        {/* Phone icon */}
                        <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <rect x="5" y="2" width="14" height="20" rx="2" ry="2"/>
                          <line x1="12" y1="18" x2="12" y2="18"/>
                    </svg>
                  </button>
                  <button
                    onClick={() => sessionMode !== "full" && toggleSessionMode()}
                    className={`p-2 rounded-full transition-all ${
                      sessionMode === "full"
                        ? "bg-brand-600 text-white shadow-sm"
                        : "text-gray-500 hover:text-gray-900"
                    }`}
                    title="Full Mode (All details)"
                  >
                    {/* Laptop icon */}
                    <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>
                      <line x1="2" y1="20" x2="22" y2="20"/>
                    </svg>
                  </button>
                </div>
                {targetUid ? (
                  <span className="inline-flex items-center gap-2 rounded-full bg-brand-50 px-3 py-1 text-xs font-semibold text-brand-700">
                    Viewing {activeAthleteName}
                  </span>
                ) : (
                  <span className="inline-flex items-center gap-2 rounded-full bg-brand-50 px-3 py-1 text-xs font-semibold text-brand-700">
                    Personal Session
                  </span>
                )}
                {isCoach && !targetUid ? (
                  <span className="inline-flex items-start gap-2 rounded-xl bg-amber-50 px-3 py-2 text-xs font-medium text-amber-700">
                    No Athlete Selected. Log Your Own Session Or Pick Someone From The Roster To Load Their Plan.
                  </span>
                ) : null}
                <button
                  type="button"
                  className="inline-flex h-9 w-9 items-center justify-center rounded-full border border-gray-200 bg-white text-gray-600 shadow-sm transition hover:border-brand-200 hover:text-brand-700"
                  onClick={() => setSessionSettingsOpen((prev) => !prev)}
                  aria-expanded={sessionSettingsOpen}
                  aria-label="Session settings"
                >
                  <svg viewBox="0 0 24 24" className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="1.6">
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M9.5 1.75h5l.73 2.2a7.5 7.5 0 012 .84l2.19-.79 2.5 4.33-1.85 1.33a7.6 7.6 0 010 2.68l1.85 1.33-2.5 4.33-2.19-.79a7.5 7.5 0 01-2 .84l-.73 2.2h-5l-.73-2.2a7.5 7.5 0 01-2-.84l-2.19.79-2.5-4.33 1.85-1.33a7.6 7.6 0 010-2.68l-1.85-1.33 2.5-4.33 2.19.79a7.5 7.5 0 012-.84l.73-2.2Z"
                    />
                    <circle cx="12" cy="12" r="3" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                </button>
                  </div>
                </>
              )}
            </div>

            {sessionSettingsOpen && (
              <div className="rounded-2xl border border-gray-200 bg-white px-4 py-3 text-xs text-gray-600 shadow-inner">
                <div className="text-[11px] uppercase tracking-wide text-gray-500">Units</div>
                <div className="mt-1 flex items-center justify-between text-sm font-semibold text-gray-900">
                  <span>{unit.toUpperCase()}</span>
                  <span className="text-xs uppercase text-gray-400">auto</span>
                </div>
              </div>
            )}

            <div className="rounded-2xl border border-gray-100 bg-gray-50/80 p-4 shadow-inner">
              <div className="grid gap-4">
                <label className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                  <span className="text-xs uppercase tracking-wide text-gray-500">Lift</span>
                  <select
                    className="rounded-xl border-2 border-brand-300 bg-white px-3 py-3 text-base font-bold text-gray-900 shadow-sm focus:border-brand-500 focus:outline-none focus:ring-2 focus:ring-brand-200"
                    value={lift}
                    onChange={(event) => {
                      setLift(event.target.value as Lift);
                      // Reset confirmation so auto-logic can run for the new lift
                      setLiftConfirmed(false);
                    }}
                  >
                    <option value="bench">Bench Press</option>
                    <option value="squat">Back Squat</option>
                    <option value="deadlift">Deadlift</option>
                  </select>
                </label>

                <div className="grid grid-cols-2 gap-4">
                  <label className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                    <span className="text-xs uppercase tracking-wide text-gray-500">Cycle</span>
                    <select
                      className="rounded-xl border-2 border-brand-300 bg-white px-3 py-3 text-base font-bold text-gray-900 shadow-sm focus:border-brand-500 focus:outline-none focus:ring-2 focus:ring-brand-200"
                      value={cycle}
                      onChange={(event) => handleCycleChange(Number(event.target.value))}
                    >
                      <option value={1}>Cycle 1</option>
                      <option value={2}>Cycle 2</option>
                      <option value={3}>Cycle 3</option>
                    </select>
                  </label>

                  <label className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                    <span className="text-xs uppercase tracking-wide text-gray-500">Week</span>
                    <select
                      className="rounded-xl border-2 border-brand-300 bg-white px-3 py-3 text-base font-bold text-gray-900 shadow-sm focus:border-brand-500 focus:outline-none focus:ring-2 focus:ring-brand-200"
                      value={week}
                      onChange={(event) => handleWeekChange(Number(event.target.value) as Week)}
                    >
                      <option value={1}>Week 1 - 65/75/85%</option>
                      <option value={2}>Week 2 - 70/80/90%</option>
                      <option value={3}>Week 3 - 75/85/95%</option>
                    </select>
                  </label>
                </div>

                <div className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                  <span className="text-xs uppercase tracking-wide text-gray-500">Training Max</span>
                  {tm && Number.isFinite(tm) ? (
                    <div className="inline-flex items-center justify-between rounded-xl border border-brand-200 bg-white px-3 py-2 text-sm font-semibold text-brand-700 shadow-sm">
                      <span>{tm} {unit}</span>
                      <span className="text-xs uppercase text-brand-600">ready</span>
                    </div>
                  ) : (
                    <div className="rounded-xl border border-dashed border-gray-300 px-3 py-2 text-sm text-gray-500">
                      Set Training Max In Calculator.
                    </div>
                  )}
                </div>
              </div>
            </div>
            {/* Visual confirmation of what's being logged - desktop only */}
            {!isMobileDevice && (
              <div className="rounded-2xl border border-brand-900/40 bg-gradient-to-br from-brand-900 via-slate-950 to-slate-900 p-4 shadow-lg">
                <div className="flex items-center justify-between gap-4">
                  <div>
                    <div className="session-now-label text-xs font-semibold uppercase tracking-wide text-sky-200">Now Logging</div>
                    <div className="text-xl font-bold text-white">
                      {LIFT_LABELS[lift]} - Cycle {cycleNumber} - Week {week}
                    </div>
                    <div className="text-sm text-slate-200">{WEEK_THEMES[week].focus}</div>
                  </div>
                  <div className="text-right">
                    <div className="text-3xl font-black text-white">
                      {week === 1 ? "65/75/85" : week === 2 ? "70/80/90" : "75/85/95"}%
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Set Status Legend - desktop only */}
            {!isMobileDevice && (
              <div className="rounded-2xl border border-gray-100 bg-white/90 px-4 py-3 text-xs text-gray-600 shadow-inner">
                <span className="font-semibold text-gray-700">Set Status Legend:</span> S = Completed All Prescribed Reps. F = Stopped Early - Record The Reps Completed.
              </div>
            )}

            <div className="space-y-4">
              {/* Warm-Up Sets */}
              <div className={`rounded-2xl border border-sky-100 bg-sky-50 ${isMobileDevice ? 'p-3' : 'p-4'} shadow-sm`}>
                {!isMobileDevice && (
                  <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
                    <div>
                      <p className="text-sm font-semibold text-sky-900">Warm-Up Ramp</p>
                      <p className="text-xs text-sky-800/80">Prime The Groove With Smooth Sets.</p>
                    </div>
                    <span className="inline-flex items-center rounded-full bg-white px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide text-sky-700">
                      Warm-Up
                    </span>
                  </div>
                )}
                {isMobileDevice && (
                  <div className="text-xs font-semibold text-sky-700 uppercase tracking-wide mb-2">Warm-Up</div>
                )}
                <div className={isMobileDevice ? "space-y-1.5" : "space-y-2"}>
                  {warm.map((set, index) => (
                    <SetRow
                      key={`warm-${index}`}
                      phase="Warm-up"
                      index={index}
                      set={set}
                      unit={unit}
                      repsLabel={set.repsDisplay}
                      outcome={warmOutcomes[index]}
                      onStatusChange={(status) => setWarmStatus(index, status)}
                      onActualChange={(value) => setWarmActual(index, value)}
                      onPlateCalc={(w) => setPlateCalcTarget(w)}
                      showActualInput
                      compact={isMobileDevice}
                    />
                  ))}
                  {warm.length === 0 && (
                    <div className="rounded-xl border border-dashed border-sky-200 px-3 py-2 text-sm text-sky-700">
                      Add A Training Max To Unlock Warm-Ups.
                    </div>
                  )}
                </div>
              </div>

              {/* Work Sets */}
              <div className={`rounded-2xl border border-brand-100 bg-brand-50 ${isMobileDevice ? 'p-3' : 'p-4'} shadow-sm`}>
                {!isMobileDevice && (
                  <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
                    <div>
                      <p className="text-sm font-semibold text-brand-700">Main Work</p>
                      <p className="text-xs text-brand-600">Own Each Top Set And Log How It Felt.</p>
                    </div>
                    <span className="inline-flex items-center rounded-full bg-white px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide text-brand-700">
                      Work Sets
                    </span>
                  </div>
                )}
                {isMobileDevice && (
                  <div className="text-xs font-semibold text-brand-700 uppercase tracking-wide mb-2">Work Sets</div>
                )}
                <div className={isMobileDevice ? "space-y-1.5" : "space-y-2"}>
                  {work.map((set, index) => {
                    const isAMRAPRow = index === work.length - 1;
                    if (isAMRAPRow) {
                      // Last work set is the AMRAP set — reps are captured in the section below
                      return isMobileDevice ? (
                        <div key={`work-${index}`} className="flex items-center justify-between gap-2 rounded-xl border border-amber-200 bg-amber-50 px-3 py-2">
                          <div className="flex items-center gap-3">
                            <span className="text-sm font-bold text-amber-900 w-6">{index + warm.length + 1}</span>
                            <button
                              type="button"
                              onClick={() => setPlateCalcTarget(set.weight)}
                              className="text-base font-bold text-amber-900 hover:text-amber-700"
                            >
                              {set.weight} <span className="font-normal text-amber-700">{unit}</span>
                            </button>
                            <span className="text-sm font-medium text-amber-700">× {set.repsDisplay}</span>
                          </div>
                          <span className="text-xs font-semibold text-amber-700 uppercase tracking-wide">AMRAP ↓</span>
                        </div>
                      ) : (
                        <div key={`work-${index}`} className="flex items-center justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3">
                          <div className="flex items-center gap-4">
                            <span className="text-sm font-bold text-amber-900 w-6">{index + warm.length + 1}</span>
                            <button
                              type="button"
                              onClick={() => setPlateCalcTarget(set.weight)}
                              className="text-base font-bold text-amber-900 hover:text-amber-700"
                            >
                              {set.weight} <span className="font-normal text-amber-700">{unit}</span>
                            </button>
                            <span className="text-sm font-medium text-amber-700">× {set.repsDisplay}</span>
                          </div>
                          <span className="text-xs font-semibold text-amber-700 uppercase tracking-wide">AMRAP — Enter Reps Below</span>
                        </div>
                      );
                    }
                    return (
                      <SetRow
                        key={`work-${index}`}
                        phase="Work"
                        index={index + warm.length}
                        set={set}
                        unit={unit}
                        repsLabel={set.repsDisplay}
                        outcome={workOutcomes[index]}
                        onStatusChange={(status) => setWorkStatus(index, status)}
                        onActualChange={(value) => setWorkActual(index, value)}
                        onPlateCalc={(w) => setPlateCalcTarget(w)}
                        showActualInput
                        compact={isMobileDevice}
                      />
                    );
                  })}
                  {work.length === 0 && (
                    <div className="rounded-xl border border-dashed border-brand-200 px-3 py-2 text-sm text-brand-700">
                      Add A Training Max To Populate The Working Weights.
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Mobile: Combined AMRAP + Save Section */}
            {isMobileDevice ? (
              <div className="rounded-2xl border-2 border-amber-300 bg-gradient-to-b from-amber-50 to-amber-100 p-4 shadow-lg space-y-4">
                <div className="text-center">
                  <div className="text-xs font-semibold uppercase tracking-wide text-amber-700 mb-1">Last Set AMRAP</div>
                  <div className="text-sm text-amber-800 mb-3">How many reps did you get on your final set?</div>
                  <div className="flex items-center justify-center gap-4">
                    <button
                      onClick={() => setAmrapReps(prev => Math.max(0, prev - 1))}
                      className="w-12 h-12 rounded-full bg-white border-2 border-amber-300 text-2xl font-bold text-amber-700 shadow-sm active:scale-95"
                    >
                      −
                    </button>
                    <div className="text-5xl font-black text-amber-900 w-20 text-center">{amrapReps}</div>
                    <button
                      onClick={() => setAmrapReps(prev => prev + 1)}
                      className="w-12 h-12 rounded-full bg-white border-2 border-amber-300 text-2xl font-bold text-amber-700 shadow-sm active:scale-95"
                    >
                      +
                    </button>
                  </div>
                </div>
                
                {amrapReps > 0 && (
                  <div className={`rounded-xl p-3 text-center ${est ? "bg-emerald-500 text-white" : "bg-gray-200 text-gray-600"}`}>
                    <div className="text-xs uppercase tracking-wide opacity-80">Est. 1RM</div>
                    <div className="text-2xl font-bold">
                      {est ? `${est} ${unit}` : "—"}
                      {prFlag && <span className="ml-2 text-yellow-300">🏆 PR!</span>}
                    </div>
                  </div>
                )}

                <button
                  className="w-full py-4 rounded-xl bg-brand-600 hover:bg-brand-700 disabled:bg-gray-300 text-white font-bold text-lg shadow-lg active:scale-[0.98] transition-all"
                  onClick={save}
                  disabled={saving || !tm || amrapReps <= 0}
                >
                  {saving ? "Saving..." : amrapReps > 0 ? "✓ Save Session" : "Enter Reps Above"}
                </button>
              </div>
            ) : (
              /* Desktop: Original separate sections */
              <>
                <div className="rounded-2xl border border-amber-100 bg-amber-50 p-4 shadow-sm">
                  <div className="grid gap-4 sm:grid-cols-2">
                    <label className="flex flex-col gap-1 text-sm font-medium text-amber-900">
                      <span className="text-xs uppercase tracking-wide text-amber-700">Last Set AMRAP Reps</span>
                      <input
                        className="rounded-xl border border-amber-200 bg-white px-3 py-2 text-sm font-semibold text-amber-900 shadow-sm focus:border-amber-400 focus:outline-none focus:ring-2 focus:ring-amber-100"
                        type="number"
                        min={0}
                        value={amrapReps}
                        onChange={(event) => setAmrapReps(Number(event.target.value) || 0)}
                      />
                    </label>
                    <label className="flex flex-col gap-1 text-sm font-medium text-amber-900">
                      <span className="text-xs uppercase tracking-wide text-amber-700">Session Notes</span>
                      <input
                        className="rounded-xl border border-amber-200 bg-white px-3 py-2 text-sm shadow-sm focus:border-amber-400 focus:outline-none focus:ring-2 focus:ring-amber-100"
                        value={note}
                        onChange={(event) => setNote(event.target.value)}
                        placeholder="Form Cues, RPE, Reminders"
                      />
                    </label>
                  </div>
                </div>

                <div
                  className={`rounded-2xl px-4 py-4 text-white shadow-lg ${
                    est ? "bg-gradient-to-r from-emerald-500 to-emerald-600" : "bg-slate-500/90"
                  }`}
                >
                  <div className="text-xs uppercase tracking-wide text-white/80">Estimated 1RM</div>
                  <div className="text-3xl font-bold">
                    {est ? `${est} ${unit}` : "Log Reps To Calculate"}
                  </div>
                  {prFlag && (
                    <div className="mt-1 text-sm font-medium text-white">
                      New PR Unlocked! Record It Before You Forget.
                    </div>
                  )}
                </div>

                <button
                  className="btn btn-primary w-full justify-center py-3 text-base"
                  onClick={save}
                  disabled={saving || !tm || amrapReps <= 0}
                >
                  {saving ? "Saving..." : "Save Session"}
                </button>
              </>
            )}
          </div>
        </div>

        {/* Recent Sessions - desktop only */}
        {!isMobileDevice && (
          <div className="card space-y-5 bg-white/95 shadow-xl ring-1 ring-gray-100/80">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold text-gray-900">Recent Sessions</h3>
              <span className="text-xs uppercase tracking-wide text-gray-400">{liftLabel}</span>
            </div>
            <div className="rounded-2xl border border-gray-100 bg-gray-50 p-3">
              <TrendMini values={estSeries} unit={unit} />
            </div>
            <ul className="space-y-3 text-sm text-gray-700">
              {history.slice(-5).map((session, index) => {
                const weekColors: Record<number, string> = {
                  1: "bg-blue-100 text-blue-700 border-blue-200",
                  2: "bg-emerald-100 text-emerald-700 border-emerald-200",
                  3: "bg-amber-100 text-amber-700 border-amber-200",
                };
                const cycleLabel = session.cycle ?? 1;
                return (
                  <li key={index} className="rounded-2xl border border-gray-100 bg-white px-3 py-2 shadow-sm">
                    <div className="flex items-center justify-between gap-3">
                      <div className="flex items-center gap-2">
                        <span className={`inline-flex items-center rounded-lg border px-2 py-0.5 text-[11px] font-bold ${weekColors[session.week] || weekColors[1]}`}>
                          C{cycleLabel} W{session.week}
                        </span>
                        <span className="font-semibold text-gray-900">
                          {session.est1rm
                            ? `est1RM ${roundToPlate(
                                session.est1rm,
                                session.unit,
                                session.unit === "lb" ? 5 : 2.5
                              )} ${session.unit}`
                            : "Logged"}
                        </span>
                      </div>
                      {session.pr ? (
                        <span className="inline-flex items-center rounded-full bg-emerald-50 px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide text-emerald-700">
                          PR
                        </span>
                      ) : null}
                    </div>
                    <div className="text-xs text-gray-500 mt-1">
                      AMRAP {session.amrap?.weight} x {session.amrap?.reps} {session.unit}
                    </div>
                  </li>
                );
              })}
              {history.length === 0 && (
                <li className="rounded-2xl border border-dashed border-gray-300 px-3 py-3 text-sm text-gray-500">
                  Log Your First Session To See Trends Here.
                </li>
              )}
            </ul>
          </div>
        )}
      </div>

      {/* Coach Tips - desktop only */}
      {!isMobileDevice && (
        <CoachTips
          week={week}
          amrapReps={amrapReps}
          unit={unit}
          tm={tm}
          est1rm={est}
          prevBest={prevBest}
          lastWeight={lastWorkWeight || 0}
          lift={lift}
        />
      )}
    </div>
  );

}

type SetRowProps = {
  phase: "Warm-up" | "Work";
  index: number;
  set: {
    pct: number;
    weight: number;
    reps: number;
  };
  unit: Unit;
  repsLabel: string;
  outcome?: SetOutcome;
  onStatusChange: (status: "" | "S" | "F") => void;
  onActualChange: (value: string) => void;
  onPlateCalc: (weight: number) => void;
  showActualInput?: boolean;
  compact?: boolean;
};

function SetRow({
  phase,
  index,
  set,
  unit,
  repsLabel,
  outcome,
  onStatusChange,
  onActualChange,
  onPlateCalc,
  showActualInput = false,
  compact = false,
}: SetRowProps) {
  const status = outcome?.status ?? "";
  const weightLabel =
    set.weight && Number.isFinite(set.weight) ? `${set.weight}` : "-";
  const percentLabel = `${Math.round(set.pct * 100)}%`;

  // Compact mobile layout - single row
  if (compact) {
    const bgColor = phase === "Work" ? "bg-brand-50" : "bg-sky-50";
    const borderColor = phase === "Work" ? "border-brand-200" : "border-sky-200";
    const textColor = phase === "Work" ? "text-brand-900" : "text-sky-900";
    return (
      <div className={`flex items-center justify-between gap-2 rounded-xl border ${borderColor} ${bgColor} px-3 py-2`}>
        <div className="flex items-center gap-3">
          <span className={`text-sm font-bold ${textColor} w-6`}>{index + 1}</span>
          <button
            type="button"
            onClick={() => onPlateCalc(set.weight)}
            className={`text-base font-bold ${textColor} hover:text-brand-600`}
          >
            {weightLabel} <span className={`${phase === "Work" ? "text-brand-700" : "text-sky-700"} font-normal`}>{unit}</span>
          </button>
          <span className={`text-sm font-medium ${phase === "Work" ? "text-brand-700" : "text-sky-700"}`}>× {repsLabel}</span>
        </div>
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => onStatusChange(status === "S" ? "" : "S")}
            className={`inline-flex h-8 w-8 items-center justify-center rounded-full border text-sm font-semibold transition ${
              status === "S"
                ? "border-emerald-500 bg-emerald-100 text-emerald-700"
                : "border-gray-300 bg-white text-gray-400"
            }`}
          >
            <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          </button>
          <button
            type="button"
            onClick={() => onStatusChange(status === "F" ? "" : "F")}
            className={`inline-flex h-8 w-8 items-center justify-center rounded-full border text-sm font-semibold transition ${
              status === "F"
                ? "border-rose-500 bg-rose-100 text-rose-700"
                : "border-gray-300 bg-white text-gray-400"
            }`}
          >
            <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={3}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        {showActualInput && status === "F" && (
          <input
            className="w-14 rounded-lg border border-gray-300 bg-white px-2 py-1 text-sm"
            type="number"
            min={0}
            value={outcome?.actualReps ?? ""}
            onChange={(event) => onActualChange(event.target.value)}
            placeholder="#"
          />
        )}
      </div>
    );
  }

  // Full desktop layout
  const accentClass =
    phase === "Work"
      ? "border-l-4 border-brand-300 bg-white shadow-sm"
      : "border-l-4 border-sky-300 bg-white shadow-sm";

  return (
    <div
      className={`flex flex-wrap items-center gap-3 rounded-2xl border border-gray-100 px-4 py-3 ${accentClass}`}
    >
      <div className="min-w-[160px]">
        <div className="flex items-center gap-2">
          <span
            className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide ${
              phase === "Work" ? "bg-brand-50 text-brand-700" : "bg-sky-50 text-sky-700"
            }`}
          >
            {phase}
          </span>
          <span className="text-xs text-gray-500">Set {index + 1}</span>
        </div>
        <div className="flex items-center gap-2 mt-0.5">
          <div className="text-sm font-semibold text-gray-900">{weightLabel}</div>
          {set.weight > 0 && (
            <button
              type="button"
              onClick={() => onPlateCalc(set.weight)}
              className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-gray-100 text-[10px] text-gray-500 hover:bg-brand-100 hover:text-brand-700 transition-colors"
              title="Show Plate Math"
            >
              💿
            </button>
          )}
        </div>
        <div className="text-xs text-gray-500">
          {percentLabel} | {repsLabel} reps
        </div>
      </div>

      <div className="ml-auto flex items-center gap-2">
        <button
          type="button"
          onClick={() => onStatusChange(status === "S" ? "" : "S")}
          className={`inline-flex h-8 w-8 items-center justify-center rounded-full border text-sm font-semibold transition ${
            status === "S"
              ? "border-emerald-500 bg-emerald-100 text-emerald-700 shadow-sm"
              : "border-gray-300 bg-white text-gray-400 hover:border-emerald-400 hover:text-emerald-600"
          }`}
        >
          <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={3}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
          </svg>
        </button>
        <button
          type="button"
          onClick={() => onStatusChange(status === "F" ? "" : "F")}
          className={`inline-flex h-8 w-8 items-center justify-center rounded-full border text-sm font-semibold transition ${
            status === "F"
              ? "border-rose-500 bg-rose-100 text-rose-700 shadow-sm"
              : "border-gray-300 bg-white text-gray-400 hover:border-rose-400 hover:text-rose-600"
          }`}
        >
          <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={3}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {showActualInput && status === "F" && (
        <div className="flex items-center gap-2 text-xs text-gray-600">
          <span className="font-semibold uppercase tracking-wide">Actual Reps</span>
          <input
            className="w-20 rounded-lg border border-gray-300 bg-white px-2 py-1 text-sm shadow-sm focus:border-brand-300 focus:outline-none focus:ring-2 focus:ring-brand-100"
            type="number"
            min={0}
            step={1}
            value={outcome?.actualReps ?? ""}
            onChange={(event) => onActualChange(event.target.value)}
            placeholder="0"
          />
        </div>
      )}
    </div>
  );
}
